import pytest

from ledger import Ledger


def test_transfer_moves_funds():
    ledger = Ledger({'a': 10, 'b': 1})
    ledger.transfer('a', 'b', 4)
    assert ledger.balances == {'a': 6, 'b': 5}


def test_insufficient_funds_rolls_back():
    ledger = Ledger({'a': 3, 'b': 1})
    with pytest.raises(ValueError):
        ledger.transfer('a', 'b', 5)
    assert ledger.balances == {'a': 3, 'b': 1}


def test_invalid_transfer_does_not_create_accounts():
    ledger = Ledger({'a': 3})
    with pytest.raises((KeyError, ValueError)):
        ledger.transfer('a', 'missing', 1)
    assert ledger.balances == {'a': 3}


def test_non_positive_amount_rejected():
    ledger = Ledger({'a': 3, 'b': 1})
    with pytest.raises(ValueError):
        ledger.transfer('a', 'b', 0)
    assert ledger.balances == {'a': 3, 'b': 1}
